public final EncryptResult encrypt(String requestPath, Map<String, ? extends Object> plainBody, String publicKeyPem, String rsaMgf1Digest) throws BadPaddingException, InvalidKeySpecException, NoSuchPaddingException, IllegalBlockSizeException, NoSuchAlgorithmException, InvalidKeyException, InvalidAlgorithmParameterException {
    Intrinsics.checkNotNullParameter(requestPath, "requestPath");
    Intrinsics.checkNotNullParameter(plainBody, "plainBody");
    Intrinsics.checkNotNullParameter(rsaMgf1Digest, "rsaMgf1Digest");
    if (publicKeyPem == null && (publicKeyPem = cachedPublicKeyPem) == null) {
        publicKeyPem = getDEFAULT_PUBLIC_KEY_PEM();
    }
    PublicKey publicKeyLoadPublicKey = loadPublicKey(publicKeyPem);
    KeyGenerator keyGenerator = KeyGenerator.getInstance("AES");
    keyGenerator.init(256);
    byte[] encoded = keyGenerator.generateKey().getEncoded();
    Intrinsics.checkNotNull(encoded);
    String strRsaEncrypt = rsaEncrypt(publicKeyLoadPublicKey, encoded, rsaMgf1Digest);
    String json = gson.toJson(plainBody);
    Intrinsics.checkNotNullExpressionValue(json, "toJson(...)");
    AesGcmResult aesGcmResultAesGcmEncrypt = aesGcmEncrypt(json, encoded);
    long jCurrentTimeMillis = System.currentTimeMillis();
    String strGenerateNonce = generateNonce(16);
    return new EncryptResult(encoded, MapsKt.linkedMapOf(TuplesKt.to("encryptedKey", strRsaEncrypt), TuplesKt.to("iv", aesGcmResultAesGcmEncrypt.getIv()), TuplesKt.to("ciphertext", aesGcmResultAesGcmEncrypt.getCiphertext()), TuplesKt.to(a.k, Long.valueOf(jCurrentTimeMillis)), TuplesKt.to("nonce", strGenerateNonce), TuplesKt.to(f.Y, hmacSha256Hex(buildRequestSignPayload(requestPath, strRsaEncrypt, aesGcmResultAesGcmEncrypt.getIv(), aesGcmResultAesGcmEncrypt.getCiphertext(), jCurrentTimeMillis, strGenerateNonce), encoded))));
}
